import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String[] a = new String[n];
        long[] key = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = next();
            int p = a[i].indexOf(':');
            long priority = Long.parseLong(a[i].substring(p + 1));
            long ts = Long.parseLong(a[i].substring(0, p));
            // Pack (priority, timestamp, original index) so a plain sort is stable on equal keys.
            key[i] = (priority * 10000 + ts) * 1000000 + i;
        }
        Arrays.sort(key);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < n; k++) sb.append(a[(int) (key[k] % 1000000)]).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	a := make([]string, n)
	pri := make([]int, n)
	ts := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = readToken()
		p := strings.IndexByte(a[i], ':')
		ts[i], _ = strconv.Atoi(a[i][:p])
		pri[i], _ = strconv.Atoi(a[i][p+1:])
	}
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	// Stable sort by (priority, timestamp) keeps input order for equal keys.
	sort.SliceStable(idx, func(x, y int) bool {
		i, j := idx[x], idx[y]
		if pri[i] != pri[j] {
			return pri[i] < pri[j]
		}
		return ts[i] < ts[j]
	})
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, i := range idx {
		w.WriteString(a[i])
		w.WriteByte('\n')
	}
}
